  await tickAndSettle(h, clock, 50);
  check("inbox drain unseen: the next tick delivers the record", readStoreRecord(h, key)?.status === "delivered" && h.promptSubmits.includes(readerDevText(1, "Waiting.")), h.promptSubmits);
